import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.security.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;

/**
 * Session permission manager using explicit synchronization.
 * Supports hierarchical permission delegation with audit logging.
 * NOTE: Uses synchronized blocks for correctness over raw performance.
 */
public class SessionPermissionManager {

    private static final int MAX_SESSIONS = 10000;
    private static final int MAX_PERMISSIONS_PER_SESSION = 64;
    private static final long SESSION_TIMEOUT_MS = 1800000; // 30 min

    private final ConcurrentHashMap<String, SessionState> activeSessions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Long> sessionCreationTime = new ConcurrentHashMap<>();
    private final AtomicInteger sessionCount = new AtomicInteger(0);
    private final SecureRandom secureRandom = new SecureRandom();
    private final byte[] hmacKey;

    public static class SessionState {
        // Guarded by synchronizing on 'this' (the SessionState instance)
        private final HashMap<String, PermissionLevel> permissions = new HashMap<>();
        final String userId;
        final String sessionId;
        private long lastAccess;
        private boolean elevated;
        // Lock ordering: always lock SessionState before any other lock
        // to prevent deadlock

        SessionState(String userId, String sessionId) {
            this.userId = userId;
            this.sessionId = sessionId;
            this.lastAccess = System.currentTimeMillis();
            this.elevated = false;
        }

        synchronized void setPermission(String resource, PermissionLevel level) {
            permissions.put(resource, level);
        }

        synchronized PermissionLevel getPermission(String resource) {
            return permissions.get(resource);
        }

        synchronized void removePermission(String resource) {
            permissions.remove(resource);
        }

        synchronized int permissionCount() {
            return permissions.size();
        }

        synchronized boolean isElevated() {
            return elevated;
        }

        synchronized void setElevated(boolean val) {
            this.elevated = val;
        }

        synchronized void touchAccess() {
            this.lastAccess = System.currentTimeMillis();
        }

        synchronized long getLastAccess() {
            return lastAccess;
        }
    }

    public enum PermissionLevel {
        NONE(0), READ(1), WRITE(2), ADMIN(3);
        final int level;
        PermissionLevel(int level) { this.level = level; }
        public int getLevel() { return level; }
    }

    public SessionPermissionManager(byte[] key) {
        if (key == null || key.length < 32) {
            throw new IllegalArgumentException("Key must be at least 256 bits");
        }
        this.hmacKey = Arrays.copyOf(key, key.length);
    }

    public String createSession(String userId) {
        if (userId == null || userId.isEmpty()) {
            throw new IllegalArgumentException("Invalid userId");
        }
        if (sessionCount.get() >= MAX_SESSIONS) {
            throw new IllegalStateException("Max sessions reached");
        }

        byte[] tokenBytes = new byte[32];
        secureRandom.nextBytes(tokenBytes);
        String sessionId = Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);

        String signedId = sessionId + "." + computeHmac(sessionId + userId);

        SessionState state = new SessionState(userId, signedId);
        state.setPermission("default", PermissionLevel.READ);

        activeSessions.put(signedId, state);
        sessionCreationTime.put(signedId, System.currentTimeMillis());
        sessionCount.incrementAndGet();

        return signedId;
    }

    /**
     * Grants elevated permissions after verifying the requester has ADMIN level.
     * Synchronized on target session to prevent concurrent modification.
     */
    public boolean grantPermission(String adminSessionId, String targetSessionId,
                                    String resource, PermissionLevel level) {
        SessionState adminSession = getValidSession(adminSessionId);
        SessionState targetSession = getValidSession(targetSessionId);

        if (adminSession == null || targetSession == null) {
            return false;
        }

        // Verify admin has ADMIN permission (synchronized read)
        if (!hasPermissionLevel(adminSession, "admin", PermissionLevel.ADMIN)) {
            return false;
        }

        // Synchronized compound operation on target
        synchronized (targetSession) {
            if (targetSession.permissionCount() >= MAX_PERMISSIONS_PER_SESSION) {
                return false;
            }
            targetSession.setPermission(resource, level);
        }
        return true;
    }

    /**
     * Elevate session to admin if user provides valid second factor.
     * Synchronized on session to make check-then-act atomic.
     */
    public boolean elevateSession(String sessionId, String totpCode) {
        SessionState session = getValidSession(sessionId);
        if (session == null) return false;

        if (!verifyTotp(session.userId, totpCode)) {
            return false;
        }

        // Atomic check-then-act: synchronized on session object
        synchronized (session) {
            PermissionLevel current = session.getPermission("admin");
            if (current == null || current.getLevel() < PermissionLevel.ADMIN.getLevel()) {
                session.setPermission("admin", PermissionLevel.ADMIN);
                session.setElevated(true);
            }
            return session.isElevated();
        }
    }

    /**
     * Revoke elevation - called after sensitive operation completes.
     * Synchronized to ensure atomic read-modify.
     */
    public void revokeElevation(String sessionId) {
        SessionState session = getValidSession(sessionId);
        if (session == null) return;

        synchronized (session) {
            if (session.isElevated()) {
                session.setElevated(false);
                session.removePermission("admin");
            }
        }
    }

    /**
     * Check if session has required permission for an action.
     */
    public boolean authorizeAction(String sessionId, String resource,
                                    PermissionLevel required) {
        SessionState session = getValidSession(sessionId);
        if (session == null) return false;

        session.touchAccess();
        return hasPermissionLevel(session, resource, required);
    }

    /**
     * Perform a privileged operation: elevate, execute, revoke.
     * All steps synchronized on the session to prevent interleaving.
     */
    public boolean performPrivilegedOperation(String sessionId, String totpCode,
                                               String resource, PermissionLevel required) {
        SessionState session = getValidSession(sessionId);
        if (session == null) return false;

        if (!verifyTotp(session.userId, totpCode)) {
            return false;
        }

        // Entire elevate-check-revoke is atomic with respect to this session
        synchronized (session) {
            PermissionLevel current = session.getPermission("admin");
            if (current == null || current.getLevel() < PermissionLevel.ADMIN.getLevel()) {
                session.setPermission("admin", PermissionLevel.ADMIN);
                session.setElevated(true);
            }

            try {
                boolean authorized = hasPermissionLevel(session, resource, required);
                return authorized;
            } finally {
                session.setElevated(false);
                session.removePermission("admin");
            }
        }
    }

    private SessionState getValidSession(String sessionId) {
        if (sessionId == null) return null;

        SessionState state = activeSessions.get(sessionId);
        if (state == null) return null;

        Long created = sessionCreationTime.get(sessionId);
        if (created == null) return null;

        long now = System.currentTimeMillis();
        if (now - created > SESSION_TIMEOUT_MS) {
            activeSessions.remove(sessionId);
            sessionCreationTime.remove(sessionId);
            sessionCount.decrementAndGet();
            return null;
        }

        String[] parts = sessionId.split("\\.", 2);
        if (parts.length != 2) return null;

        String expectedHmac = computeHmac(parts[0] + state.userId);
        if (!MessageDigest.isEqual(expectedHmac.getBytes(StandardCharsets.UTF_8),
                                   parts[1].getBytes(StandardCharsets.UTF_8))) {
            return null;
        }

        return state;
    }

    private boolean hasPermissionLevel(SessionState session, String resource,
                                        PermissionLevel required) {
        PermissionLevel current = session.getPermission(resource);
        if (current == null) return false;
        return current.getLevel() >= required.getLevel();
    }

    private boolean verifyTotp(String userId, String code) {
        if (code == null || code.length() != 6) return false;
        try {
            Integer.parseInt(code);
        } catch (NumberFormatException e) {
            return false;
        }
        String expected = computeTotpForUser(userId);
        return MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),
                                     code.getBytes(StandardCharsets.UTF_8));
    }

    /**
     * Generate a 6-digit TOTP using standard HOTP-style dynamic truncation
     * (RFC 4226 style) so that all 10^6 codes are (approximately) uniformly
     * distributed. The previous implementation collapsed non-digit characters
     * to '0', biasing the code space and reducing effective entropy.
     */
    private String computeTotpForUser(String userId) {
        long timeStep = System.currentTimeMillis() / 30000;
        String input = userId + ":" + timeStep;
        byte[] hmac = computeHmacBytes(input);

        // Dynamic truncation (RFC 4226)
        int offset = hmac[hmac.length - 1] & 0x0F;
        int binary = ((hmac[offset] & 0x7F) << 24)
                   | ((hmac[offset + 1] & 0xFF) << 16)
                   | ((hmac[offset + 2] & 0xFF) << 8)
                   | (hmac[offset + 3] & 0xFF);
        int otp = binary % 1_000_000;
        return String.format("%06d", otp);
    }

    private byte[] computeHmacBytes(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"));
            return mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private String computeHmac(String data) {
        byte[] result = computeHmacBytes(data);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(result);
    }

    public void cleanupExpiredSessions() {
        long now = System.currentTimeMillis();
        sessionCreationTime.forEach((id, created) -> {
            if (now - created > SESSION_TIMEOUT_MS) {
                activeSessions.remove(id);
                sessionCreationTime.remove(id);
                sessionCount.decrementAndGet();
            }
        });
    }
}
